#include <iostream>
#include <vector>
#include <string>

int main() {
    int total;
    std::cin >> total;
    std::cin.ignore(); // consume newline after integer input
    std::string line;
    std::getline(std::cin, line);

    int maxLength = 0;
    std::vector<std::string> words;
    std::string buffer;
    bool insideBrackets = false;

    for (char ch : line) {
        if (ch == '(') {
            insideBrackets = true;
            if (buffer.length() > maxLength) maxLength = buffer.length();
            buffer.clear();
        } else if (ch == ')') {
            insideBrackets = false;
            if (!buffer.empty()) {
                words.push_back(buffer);
                buffer.clear();
            }
        } else if (isalpha(ch)) {
            buffer += ch;
        } else if (ch == '_') {
            if (insideBrackets) {
                if (!buffer.empty()) {
                    words.push_back(buffer);
                    buffer.clear();
                }
            } else {
                if (buffer.length() > maxLength) maxLength = buffer.length();
                buffer.clear();
            }
        }
    }
    if (buffer.length() > maxLength) maxLength = buffer.length();

    std::cout << maxLength << " " << words.size() << std::endl;

    return 0;
}
